-- Airlinerra Phase 5 Batch 6, 2026-10-26 — 20 evidence-only runway end observations.
-- Applied to private Supabase project hwllkabgzaynalahvkpz; this archive provides idempotent replay.
-- Note: LDA values are NULL because original authoritative FAA/NASR values were NOT verified.
-- 19-ish metre gross margin is NOT an official LDA; displaced-threshold nominal is only an estimate.
-- Two Fairfield Municipal (FWC) records have NULL source cycle and CITY_OPERATOR_SECONDARY level.
-- Must run after Phase 5 table migrations. Does not approve any airport.
ON CONFLICT (airport_key,runway_end) DO NOTHING;

SELECT p.faa_identifier,d.runway_end,d.screening_status,d.source_published_lda_ft,d.source_cycle_date,d.commercial_admission_status
FROM airlinerra.airport_expansion_phase5_runway_directions d
JOIN airlinerra.airport_expansion_phase5_gate_reviews p USING(airport_key)
WHERE p.phase5_batch_identifier='US_EXPANSION_PHASE5_MISSING_LDA_BATCH_06_2026_10_26'
ORDER BY p.faa_identifier,d.runway_end;
